#include <ansi.h>

inherit NPC;
inherit F_UNIQUE;
inherit F_MASTER;
int do_skills(string arg);

void create() {
    set_name("独臂神尼", ({ "dubi shenni", "dubi" }));
    set("gender", "女性");
    set("age", 44);
    set("str", 25);
    set("dex", 20);
    set("long", "这是一位白衣女尼，手握拂尘，目视前方。\n" +
        "一只长袖空空如也，显是断了一臂，尽管如此，\n" +
        "仍然掩不住她迷人的风采。\n");
    set("combat_exp", 200000);
    set("shen_type", 1);
    set("attitude", "peaceful");

    set_skill("whip", 150);
    set_skill("force", 90);
    set_skill("unarmed", 90);
    set_skill("dodge", 150);
    set_skill("parry", 90);
    set_skill("qiufeng-chenfa", 150);
    set_skill("shenxing-baibian", 150);
    map_skill("whip", "qiufeng-chenfa");
    map_skill("parry", "qiufeng-chenfa");
    map_skill("dodge", "shenxing-baibian");

    set_temp("apply/attack", 100);
    set_temp("apply/defense", 100);
    set_temp("apply/armor", 40);
    set_temp("apply/damage", 100);
    set("neili", 1500);
    set("max_neili", 1500);
    set("jiali", 100);
    set("inquiry", ([
        "阿珂": "神尼叹了一口气，说道：她是我的得意弟子，\n"
        "人长得挺美，唉，只可惜被韦小宝骗去了。\n",
    ]));
    setup();
